      { q: { de: "Welchen Beruf übte er als junger Mann aus?", sr: "Чиме се бавио као младић?" }, options: [{ de: "Zimmermann", sr: "Дрводеља" }, { de: "Lehrer", sr: "Учитељ" }, { de: "Arzt", sr: "Лекар" }], correct: 0 }
